def get_unlocked_data():
    d = zlib.decompress(base64.b64decode(ENC_DATA_1))
    for mk in reversed(KEYS_POOL_1):
        mk_bytes = mk.encode('utf-8')
        c_key = hashlib.sha256(mk_bytes).digest()
        c_nonce = hashlib.sha256(mk_bytes + b'nonce').digest()[:12]
        d = chacha20(c_key, c_nonce, d)
    return d.decode('utf-8', errors='ignore')
